# C++ 

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const int MOD = 10007;

    string s;
    if (!getline(cin, s)) return 0;

    int n = (int)s.size() / 5;           // 因为每段都是 "(x+d)"，长度为5
    vector<int> a(n);

    // 解析每个因子 (x±d) -> a_k = ±d
    for (int k = 0; k < n; ++k) {
        int base = 5 * k;
        char op = s[base + 2];           // '+' 或 '-'
        int d = s[base + 3] - '0';       // '1'..'9'
        int val = (op == '-') ? -d : d;
        // 归一化到 [0, MOD)
        int aval = (val % MOD + MOD) % MOD;
        a[k] = aval;
    }

    // 前缀积 L[i] = a[0]*...*a[i-1]，L[0]=1
    vector<int> L(n, 1), R(n, 1);
    for (int i = 1; i < n; ++i) {
        L[i] = (int)((1LL * L[i - 1] * a[i - 1]) % MOD);
    }
    // 后缀积 R[i] = a[i+1]*...*a[n-1]，R[n-1]=1
    for (int i = n - 2; i >= 0; --i) {
        R[i] = (int)((1LL * R[i + 1] * a[i + 1]) % MOD);
    }

    // 答案：sum L[i]*R[i]
    long long ans = 0;
    for (int i = 0; i < n; ++i) {
        ans += 1LL * L[i] * R[i] % MOD;
        if (ans >= (1LL<<60)) ans %= MOD; // 防长整溢出的小优化（可有可无）
    }
    cout << (ans % MOD + MOD) % MOD << "\n";
    return 0;
}
```

