    # suffix R[i] = product a[i+1..n-1], R[n-1]=1
    R = [1] * n
    for i in range(n - 2, -1, -1):
        R[i] = (R[i + 1] * a[i + 1]) % MOD

    # sum L[i]*R[i]
    ans = 0
    for i in range(n):
        ans = (ans + L[i] * R[i]) % MOD

    print(ans)

if __name__ == "__main__":
    main()
