import sys

MOD = 10007

def main():
    s = sys.stdin.readline().strip()
    n = len(s) // 5          # 因子个数
    a = []

    # 解析每个因子 (t+d) 或 (t-d)
    for k in range(n):
        base = 5 * k
        op = s[base + 2]                 # '+' 或 '-'
        d = ord(s[base + 3]) - ord('0')  # 数字 1..9
        val = -d if op == '-' else d
        # 映射到 [0, MOD) 区间
        a.append((val % MOD + MOD) % MOD)

    # 前缀积 L[i] = a[0] * ... * a[i-1] (mod MOD), L[0]=1
    L = [1] * n
    for i in range(1, n):
        L[i] = (L[i - 1] * a[i - 1]) % MOD

    # 后缀积 R[i] = a[i+1] * ... * a[n-1] (mod MOD), R[n-1]=1
    R = [1] * n
    for i in range(n - 2, -1, -1):
        R[i] = (R[i + 1] * a[i + 1]) % MOD

    # 求和
    ans = 0
    for i in range(n):
        ans = (ans + L[i] * R[i]) % MOD

    print(ans)

if __name__ == "__main__":
    main()
```

